"""Validate the precise RGB8/filter-0 fixtures generated by integration tests.

This is not a general PNG decoder and is never used to grade student images.
Compressed byte streams may differ across zlib implementations; pixels may not.
"""
from __future__ import annotations

import struct
import zlib


def assert_solid_fixture(data: bytes, rgb: tuple[int, int, int]) -> None:
    assert data[:8] == b"\x89PNG\r\n\x1a\n", "Invalid fixture PNG signature"
    offset = 8
    chunks: list[tuple[bytes, bytes]] = []
    while offset < len(data):
        assert offset + 12 <= len(data), "Truncated chunk"
        length = struct.unpack_from("!I", data, offset)[0]
        end = offset + 12 + length
        assert end <= len(data), "Truncated payload"
        kind = data[offset + 4:offset + 8]
        payload = data[offset + 8:end - 4]
        crc = struct.unpack_from("!I", data, end - 4)[0]
        assert zlib.crc32(kind + payload) & 0xffffffff == crc, "Invalid chunk CRC"
        chunks.append((kind, payload))
        offset = end
    assert len(chunks) >= 3, "Missing PNG chunks"
    assert chunks[0] == (b"IHDR", struct.pack("!2I5B", 256, 192, 8, 2, 0, 0, 0)), "Fixture dimensions or format changed"
    assert chunks[-1] == (b"IEND", b""), "Missing IEND"
    assert all(kind == b"IDAT" for kind, _ in chunks[1:-1]), "Unexpected fixture chunk"
    packed = b"".join(payload for _, payload in chunks[1:-1])
    expected = (b"\0" + bytes(rgb) * 256) * 192
    decoder = zlib.decompressobj()
    raw = decoder.decompress(packed, len(expected) + 1)
    assert decoder.eof and not decoder.unused_data and not decoder.unconsumed_tail, "Invalid compressed stream"
    assert raw == expected, "Fixture pixels changed"
